INSERT INTO "feedback" VALUES(1,6,NULL,5,'Taste','POSITIVE','Masala Dosa was crisp and the sambhar was steaming hot!','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(2,6,NULL,5,'Taste','POSITIVE','Vada Pav was super authentic and spicy. Great quick bite between lectures.','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(3,6,NULL,5,'Quality','POSITIVE','Cold coffee is always top tier. Amazing texture and ice cream blend.','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(4,6,NULL,3,'Waiting Time','NEUTRAL','The waiting time for Biryani was a bit too long during peak lunch break (15 mins).','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(5,6,NULL,5,'Price','POSITIVE','Special Deluxe Thali is very affordable and filling for students. Best value for money.','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(6,6,NULL,3,'Cleanliness','NEUTRAL','Canteen tables were slightly crowded today, need more seats near the window.','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(7,6,NULL,5,'Service','POSITIVE','Friendly staff and very fast counter service on morning idlis!','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(8,6,NULL,2,'Quality','NEGATIVE','Sandwich cheese was cold and not melted properly.','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(9,6,NULL,4,'Taste','POSITIVE','Samosa crust was slightly oily today, but the green mint chutney was fantastic.','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(10,6,NULL,5,'Service','POSITIVE','Ordering ahead saved me 20 minutes in line! Love the smart canteen app.','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(11,6,NULL,5,'Quantity','POSITIVE','Portion size of French fries was very generous for ₹60.','2026-08-22 21:33:10');
INSERT INTO "feedback" VALUES(12,6,NULL,5,'Price','POSITIVE','Prices are extremely student-friendly, especially the combo meals.','2026-08-22 21:33:10');
INSERT INTO "food_categories" VALUES(1,'Breakfast','Fresh, wholesome morning energy boosters to start your college day right','fa-sun','https://images.unsplash.com/photo-1533089860892-a7c6f0a88666?w=500&auto=format&fit=crop&q=80',1);
INSERT INTO "food_categories" VALUES(2,'Snacks & Quick Bites','Crispy, savory snacks perfect for quick class breaks','fa-cookie-bite','https://images.unsplash.com/photo-1601050690597-df0568f70950?w=500&auto=format&fit=crop&q=80',2);
INSERT INTO "food_categories" VALUES(3,'Main Course','Hearty, filling meals, bowls, thalis, and aromatic biryanis','fa-bowl-food','https://images.unsplash.com/photo-1589301760014-d929f3979dbc?w=500&auto=format&fit=crop&q=80',3);
INSERT INTO "food_categories" VALUES(4,'Beverages & Shakes','Chilled coffees, fresh juices, hot chai, and refreshing coolers','fa-mug-hot','https://images.unsplash.com/photo-1517256064527-09c73fc73e38?w=500&auto=format&fit=crop&q=80',4);
INSERT INTO "food_categories" VALUES(5,'Desserts & Bakery','Sweet treats, ice creams, and freshly baked delights','fa-cake-candles','https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=500&auto=format&fit=crop&q=80',5);
INSERT INTO "food_categories" VALUES(6,'Value Combos','Budget-friendly student meal combos with heavy savings','fa-layer-group','https://images.unsplash.com/photo-1544025162-d76694265947?w=500&auto=format&fit=crop&q=80',6);
INSERT INTO "food_items" VALUES(1,'Masala Dosa','Crispy golden fermented crepe stuffed with aromatic spiced potatoes, served with hot sambhar & fresh coconut chutney.',1,60.0,'https://images.unsplash.com/photo-1668236543090-82eba5ee5976?w=600&auto=format&fit=crop&q=80','Rice batter, Spiced potato filling, Mustard seeds, Curry leaves, Coconut chutney, Sambhar',1,1,52,8,320,'Medium',4.8,128,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(2,'Steamed Idli Sambar (2 pcs)','Ultra-soft, fluffy steamed rice cakes served submerged in rich lentil stew and tangy coconut dip.',1,45.0,'https://images.unsplash.com/photo-1589301760014-d929f3979dbc?w=600&auto=format&fit=crop&q=80','Rice, Urad dal, Sambhar spices, Drumsticks, Coconut chutney',1,1,60,5,180,'Mild',4.6,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(3,'Crispy Medu Vada (2 pcs)','Deep-fried golden doughnut-shaped lentil fritters, crisp on outside and soft inside.',1,50.0,'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop&q=80','Black gram, Peppercorn, Ginger, Curry leaves, Green chili',1,1,60,6,280,'Medium',4.7,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(4,'Poha with Sev & Peanuts','Light, fluffy Maharashtrian tempered flattened rice with roasted crunch and fresh lemon zest.',1,35.0,'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=600&auto=format&fit=crop&q=80','Flattened rice, Roasted peanuts, Turmeric, Mustard, Sev, Lemon juice',1,1,60,4,210,'Mild',4.5,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(5,'Mumbai Vada Pav','The quintessential campus favorite! Spiced potato fritter in a soft bun with fiery garlic chutney.',2,25.0,'https://images.unsplash.com/photo-1606491956689-2ea866880c84?w=600&auto=format&fit=crop&q=80','Potato patty, Gram flour, Fresh pav bun, Garlic dry chutney, Fried green chili',1,1,60,3,290,'Spicy',4.9,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(6,'Punjabi Samosa (2 pcs)','Crisp, flaky pastry pockets stuffed with cumin-spiced potatoes and peas.',2,35.0,'https://images.unsplash.com/photo-1601050690597-df0568f70950?w=600&auto=format&fit=crop&q=80','Flour pastry, Spiced potatoes, Green peas, Coriander, Mint chutney, Tamarind chutney',1,1,60,4,310,'Medium',4.7,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(7,'Kolhapuri Misal Pav','Fiery sprouted bean curry topped with crunchy farsan and served with buttered pav.',2,65.0,'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop&q=80','Sprouted moth beans, Spicy rassa gravy, Farsan, Chopped onions, Lemon, Pav',1,1,60,7,420,'Spicy',4.8,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(8,'Grilled Cheese Sandwich','Golden grilled buttery toast loaded with melted gooey cheese and signature herbs.',2,70.0,'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?w=600&auto=format&fit=crop&q=80','Brown bread, Cheddar & Mozzarella cheese, Herb butter, Green chutney',1,1,60,8,380,'Mild',4.6,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(9,'Paneer Tikka Kathi Roll','Smoky tandoori paneer wrapped in flaky paratha with sliced onions and zesty mint dip.',2,90.0,'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop&q=80','Marinated paneer cubes, Paratha wrap, Onions, Mint yogurt sauce, Chaat masala',1,1,60,10,450,'Spicy',4.9,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(10,'Crispy French Fries (Peri-Peri)','Crunchy golden potato fries tossed in fiery African bird''s eye chili seasoning.',2,60.0,'https://images.unsplash.com/photo-1576107232684-1279f3908594?w=600&auto=format&fit=crop&q=80','Potato batons, Peri-peri spice mix, Garlic mayo, Tomato ketchup',1,1,60,6,340,'Spicy',4.7,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(11,'Cheesy Veg Burger','Loaded vegetable patty with melted cheese, crisp greens, and creamy dressing in a toasted brioche bun.',2,85.0,'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?w=600&auto=format&fit=crop&q=80','Crisp veg patty, Sesame bun, Cheese slice, Lettuce, Tomato, Thousand Island dressing',1,1,60,9,460,'Medium',4.6,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(12,'Farmhouse Cheesy Pizza (8 inch)','Freshly baked thin-crust pizza topped with gooey mozzarella, crunchy bell peppers, corn, and herbs.',2,140.0,'https://images.unsplash.com/photo-1513104890138-7c749659a591?w=600&auto=format&fit=crop&q=80','Pizza dough, San Marzano tomato sauce, Mozzarella, Bell peppers, Sweet corn, Olives',1,1,60,14,620,'Medium',4.8,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(13,'Hyderabadi Veg Dum Biryani','Slow-cooked fragrant long-grain basmati rice layered with vegetables, saffron, and rich caramelized onions.',3,120.0,'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=600&auto=format&fit=crop&q=80','Basmati rice, Saffron, Fried onions, Paneer, Mixed vegetables, Dum spices, Raita',1,1,59,12,540,'Spicy',4.9,121,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(14,'Special Deluxe Student Thali','The ultimate balanced feast! Rich paneer butter masala, yellow dal, hot rotis, fragrant rice & sweet.',3,110.0,'https://images.unsplash.com/photo-1610057099443-fde8c4d50f91?w=600&auto=format&fit=crop&q=80','Paneer curry, Dal tadka, 3 Butter Rotis, Steamed Jeera Rice, Gulab Jamun, Salad, Pickle',1,1,60,8,680,'Medium',4.9,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(15,'Paneer Butter Masala with 2 Naan','Soft succulent paneer cubes simmered in velvety makhani gravy served with piping hot butter naans.',3,130.0,'https://images.unsplash.com/photo-1631452180519-c014fe946bc7?w=600&auto=format&fit=crop&q=80','Cottage cheese, Cashew tomato gravy, Fresh cream, Kasuri methi, Butter garlic naan',1,1,59,12,590,'Medium',4.8,121,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(16,'Chole Bhature (2 pcs)','Tangy, dark spiced chickpea curry served with giant balloon-puffed fried leavened breads.',3,95.0,'https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?w=600&auto=format&fit=crop&q=80','Chickpeas, Pomegranate seeds, Spices, Puffed bhature, Pickled onion, Mint sauce',1,1,60,10,650,'Spicy',4.8,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(17,'Dal Khichdi with Desi Ghee','Soulful, easily digestible comfort meal topped with aromatic garlic tadka and pure desi ghee.',3,80.0,'https://images.unsplash.com/photo-1546833999-b9f581a1996d?w=600&auto=format&fit=crop&q=80','Rice, Moong dal, Cumin tadka, Garlic, Desi ghee, Papad, Mango pickle',1,1,60,7,390,'Mild',4.7,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(18,'Signature Cold Coffee with Ice Cream','Thick, creamy, iced frothy espresso milkshake crowned with a velvety scoop of vanilla ice cream.',4,55.0,'https://images.unsplash.com/photo-1517256064527-09c73fc73e38?w=600&auto=format&fit=crop&q=80','Arabica coffee blend, Full cream milk, Vanilla ice cream scoop, Chocolate syrup drizzle',1,1,48,4,240,'Mild',4.9,132,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(19,'Special Masala Chai (Kulhad)','Steaming hot traditional spiced milk tea served in an earthen clay kulhad for that authentic aroma.',4,20.0,'https://images.unsplash.com/photo-1561336313-0bd5e0b27ec8?w=600&auto=format&fit=crop&q=80','Assam black tea, Crushed cardamom, Ginger, Cinnamon, Whole milk, Jaggery option',1,1,60,3,90,'Mild',4.9,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(20,'Sweet Punjabi Mango Lassi','Refreshing and rich chilled yogurt smoothie blended with ripe sweet mango pulp.',4,45.0,'https://images.unsplash.com/photo-1546173159-315724a31696?w=600&auto=format&fit=crop&q=80','Thick curd, Alphonso mango pulp, Cardamom, Pistachio slivers',1,1,60,3,220,'Mild',4.7,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(21,'Fresh Mint Lemonade (Mojito)','Crisp sparkling lime and mint cooler with a refreshing dash of rock salt.',4,35.0,'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=600&auto=format&fit=crop&q=80','Fresh lime juice, Muddled mint leaves, Soda, Black salt, Cumin powder',1,1,60,3,80,'Mild',4.6,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(22,'Hot Gulab Jamun (2 pcs)','Melt-in-the-mouth fried dough dumplings soaked in warm fragrant cardamom and rose syrup.',5,40.0,'https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=600&auto=format&fit=crop&q=80','Mawa / Khoya, Rosewater sugar syrup, Cardamom, Almond flakes',1,1,55,2,290,'Mild',4.8,125,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(23,'Chocolate Brownie with Fudge','Gooey, decadent dark chocolate walnut brownie smothered in hot bittersweet fudge sauce.',5,65.0,'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?w=600&auto=format&fit=crop&q=80','Dark cocoa, Butter, Chocochips, Warm fudge sauce, Walnuts',1,1,57,3,360,'Mild',4.9,123,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(24,'Power Combo: 2 Vada Pav + Cold Coffee','The undisputed #1 student favorite! Save ₹15 with this ultimate hunger-busting combo.',6,90.0,'https://images.unsplash.com/photo-1606491956689-2ea866880c84?w=600&auto=format&fit=crop&q=80','2 Mumbai Vada Pav, 1 Chilled Signature Cold Coffee',1,1,60,5,680,'Medium',4.9,120,'2026-08-22 16:03:02');
INSERT INTO "food_items" VALUES(25,'Lunch Combo: Biryani + Cold Drink + Gulab Jamun','Complete 3-course lunch box deal engineered for satisfying midday cravings.',6,160.0,'https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?w=600&auto=format&fit=crop&q=80','1 Veg Dum Biryani, 1 Mint Cooler, 1 Hot Gulab Jamun',1,1,60,10,820,'Spicy',4.9,120,'2026-08-22 16:03:02');
